-  return NS_ERROR_NOT_IMPLEMENTED;
+  nsCOMPtr<nsIDatabaseCore> database = components::DatabaseCore::Service();
+  nsCOMPtr<nsIFolderDatabase> folderDatabase = database->GetFolders();
